def _is_missing(value):
    """True for None and NaN-like scalars, without raising on odd types."""
    if value is None:
        return True
    try:
        return bool(pd.isna(value))
    except (TypeError, ValueError):
        return False


def _as_number(value):
    """Return value as a finite float, or None if it is not numeric."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def sort_palette_values(values):
    """Deterministically order values for color assignment.

    Numeric and numeric-looking values (numpy cluster ids, or the strings read
    back out of a color table) sort numerically, everything else sorts lexically
    by str(), and missing values come last. Unlike sorting the raw values, this
    is safe when a column mixes types.

    Args:
        values: an iterable of values.

    Returns:
        A list holding the same values, in assignment order.
    """
    numeric = []
    other = []
    missing = []
    for value in values:
        if _is_missing(value):
            missing.append(value)
            continue
        number = _as_number(value)
        if number is None:
            other.append(value)
        else:
            numeric.append((number, str(value), value))
    numeric.sort(key=lambda item: item[:2])
    other.sort(key=str)
    return [item[2] for item in numeric] + other + missing


def get_palette(values, max_groups=None, offset=0):
    """Map values to distinct colors.

    Colors are assigned in sort_palette_values order and cycle over
    DISTINCT_COLORS, so numerically adjacent values always differ. Values
    len(DISTINCT_COLORS) apart do reuse a color; --max_color_groups exists for
    when that is still too many groups to read.

    Args:
        values: a pandas Series of per-item values, or an iterable of the unique
            values. A Series lets max_groups rank groups by frequency.
        max_groups (int, optional): if set, only this many groups get a distinct
            color and every remaining group shares OTHER_COLOR. Groups are ranked
            by frequency when values is a Series, otherwise by sort order.
            Defaults to None, meaning every group gets a color.
        offset (int, optional): skip this many colors at the start of
            DISTINCT_COLORS, so that a second column can be colored without
            reusing the colors given to a first column with that many values.
            Defaults to 0.

    Returns:
        dict mapping each distinct value to an "#RRGGBB" string. Missing values
        are collected under the key None and colored OTHER_COLOR.

    Raises:
        InputError: if offset is negative.
    """
    if offset < 0:
        raise InputError(f"The palette offset must be 0 or more, not {offset}.")
    if isinstance(values, pd.Series):
        unique_values = list(values.unique())
        ranked = list(values.value_counts().index)  # most common first, missing dropped
    else:
        unique_values = list(values)
        ranked = None

    present = [value for value in unique_values if not _is_missing(value)]
    has_missing = len(present) < len(unique_values)

    keep = None
    if max_groups is not None and max_groups < len(present):
        if ranked is None:
            ranked = sort_palette_values(present)
        keep = set(ranked[:max(max_groups, 0)])

    out = dict()
    colored = 0
    for value in sort_palette_values(present):
        if keep is None or value in keep:
            out[value] = DISTINCT_COLORS[(offset + colored) % len(DISTINCT_COLORS)]
            colored += 1
        else:
            out[value] = OTHER_COLOR
    if has_missing:
        out[None] = OTHER_COLOR
    return out


def normalize_color_hex(color_hex):
    '''
        takes in a string of the format:
            (#?)([a-fA-F0-9]{6})
        raises an exception if string is not of expected format
        otherwise, returns string in format #[A-F0-9]{6}
    '''
    color_hex = color_hex.strip().upper()
    matches = re.match(r'^(#?)([A-F0-9]{6})$',color_hex)
    if not matches:
        raise InputError(f"Color code not recognized: {color_hex}")
    else:
        return "#" + matches.group(2)
    
def read_color_table(color_table):
    """
        input: path or handle to a tsv with two columns and no header
                columns are: domain id, hex color. For example: CCDB   cc0000
        output:
            a dict of domain: hex color
                for example: {"CCDB": "#CC0000"}
    """
    
    file_handle, input_type = open_if_is_name(color_table)
    out = dict()

    for line in file_handle:
        line = line.strip()
        if len(line) >0:
            parts = line.split("\t")
            if len(parts) != 2:
                raise RuntimeError(f"badly formatted line in color table: {line}")
            if parts[0] not in out:
                out[parts[0]] = normalize_color_hex(parts[1])
            else:
                raise InputError(f"domain specified multiple times in color table: {parts[0]}")

    if input_type == "name":
        file_handle.close()
    
    return out


AUTO_COLORS = (
    "#3BA3EC", "#38A9C5", "#34AF8C", "#AE9D31", "#F77468", "#B287F4", "#39A7D5", "#DC8932",
    "#37AAB9", "#9591F4", "#BB9832", "#F560E4", "#F37A32", "#77AB31", "#50B131", "#E866F4",
    "#9FA131", "#35AE99", "#F66AB7", "#F66DA2", "#CC7AF4", "#F77189", "#33B07A", "#CA9232",
    "#32B25C", "#F565CC", "#36ACAE", "#6E9BF4", "#8EA631", "#36ADA4",
)
"""The colors AutoColormap hands out, in order: seaborn's 30-color husl palette
(``color_palette('husl', n_colors=30)``), upper-cased and shuffled with ``random.Random(12)``."""


class AutoColormap:
    """Assigns colors to names on first use, cycling through the 30 AUTO_COLORS."""
    def __init__(self):
        self.next_color = 0
        self.color_list = list(AUTO_COLORS)
        self.color_map = dict()
    def __getitem__(self, key: str) -> str:
        if key not in self.color_map:
            self.color_map[key] = self.color_list[self.next_color]
            self.next_color = (self.next_color + 1) % len(self.color_list)
        return self.color_map[key]
    def __contains__(self, key: str) -> bool:
        self[key]  # every name gets a color
        return True
    def items(self):
        return self.color_map.items()
